import { atom, read, update } from "claude-code";
import type { Register } from "claude-code";
import { LOG, parseLog, parsedNames } from "./logparse";
import { selfCheckOf } from "./selfcheck";
import {
  LIMITS,
  TROUBLE,
  addPlugin,
  addRecord,
  emptyBuffer,
  emptyRegistry,
  hintTextOf,
  isEngineCall,
  isTraced,
  keyOf,
  makeRecord,
  sameTrouble,
  slowdownsOf,
  snapshotOf,
  trackSuspect,
} from "./trace";
import type {
  LogStatus,
  ParsedLog,
  Slowdown,
  Suspect,
  TraceRecord,
  TroubleItem,
} from "./types/index";
import { ROW_PREFIX, pane } from "./views/pane";

// Thin entry. The engine follows `$` only into functions declared in this
// file, so every `$` call and every hook sits here and the logic modules take
// plain data. The star hook writes to the `buffer` atom, which no render
// reads. A one-second timer, armed only while the pane is open, copies it to
// the `snapshot` atom the pane draws from.

const registryAtom = atom(
  { plugin: "chain-inspector", key: "registry" } as const,
  emptyRegistry(),
);
const bufferAtom = atom(
  { plugin: "chain-inspector", key: "buffer" } as const,
  emptyBuffer(),
);
const snapshotAtom = atom(
  { plugin: "chain-inspector", key: "snapshot" } as const,
  null,
);
const tracingAtom = atom(
  { plugin: "chain-inspector", key: "tracing" } as const,
  true,
);
const paneOpenAtom = atom(
  { plugin: "chain-inspector", key: "paneOpen" } as const,
  false,
);
const selectedAtom = atom(
  { plugin: "chain-inspector", key: "selected" } as const,
  null,
);

const troubleAtom = atom(
  { plugin: "chain-inspector", key: "trouble" } as const,
  [],
);
const hintTailAtom = atom(
  { plugin: "chain-inspector", key: "hintTail" } as const,
  null,
);

const logStatusAtom = atom(
  { plugin: "chain-inspector", key: "logStatus" } as const,
  "none" as LogStatus,
);

const USAGE = "usage: /chain [open|on|off]";

// What the last read of a session's debug log gave. Module memory, keyed by
// session id, so a read inside `LOG.minGapMs` of the last one reuses it.
type LogCache = {
  readAt: number | null;
  log: ParsedLog | null;
  frozen: boolean;
  pending: Promise<void> | null;
};
const logCache = new Map<string, LogCache>();

// One read of the log file into `slot`.
async function fetchLog($: any, id: string, slot: LogCache): Promise<void> {
  let dir = await $.env.get("CLAUDE_CONFIG_DIR");
  if (!dir) {
    const home = (await $.env.get("HOME")) ?? (await $.env.get("USERPROFILE"));
    if (!home) return;
    dir = `${home}/.claude`;
  }
  const path = `${dir}/debug/${id}.txt`;
  let size = 0;
  try {
    size = Number((await $.fs.stat(path)).size) || 0;
  } catch {
    // No stat answer. The read below settles whether the log exists.
  }
  if (size > LOG.maxBytes) {
    slot.frozen = true;
    await update($, logStatusAtom, () => "frozen" as LogStatus);
    return;
  }
  try {
    slot.log = parseLog(String(await $.fs.read(path)));
  } catch {
    // No log file, which is what a run without `--debug` leaves.
  }
  await update(
    $,
    logStatusAtom,
    () => (slot.log ? "reading" : "none") as LogStatus,
  );
}

// After each completed read, checks every open suspect against the fresh
// cache, so a suspect raised inside the reader's gap is confirmed by the next
// read. A suspect that draws its own component is left to the pane. Never
// throws.
async function recheckSuspects($: any, slot: LogCache): Promise<void> {
  try {
    if (slot.frozen || !slot.log) return;
    const log = slot.log;
    const buffer = await read($, bufferAtom);
    const open = Object.values(buffer.suspects).filter(
      (s) =>
        parsedNames(log, s.plugin, s.event) &&
        !(
          s.event === "ui.render" &&
          (buffer.ownedEnders ?? []).includes(s.plugin)
        ),
    );
    if (open.length === 0) return;
    const at = Number(await $.clock.now());
    const found: TroubleItem[] = open.map((s) => ({
      kind: "ender",
      plugin: s.plugin,
      key: s.key,
      event: s.event,
      at,
    }));
    let fresh: TroubleItem[] = [];
    await update($, troubleAtom, (t) => {
      fresh = found.filter((f) => !t.some((x) => sameTrouble(x, f)));
      return fresh.length > 0 ? [...t, ...fresh] : t;
    });
    const newest = fresh[fresh.length - 1];
    if (newest) await announce($, newest);
  } catch (err) {
    $.ui.log(
      `chain-inspector: suspect re-check failed (${String((err as any)?.message ?? err)})`,
    );
  }
}

// Reads the debug log into the cache, at most once per `LOG.minGapMs`. Stats it
// first; past `LOG.maxBytes` it freezes readings for the session and keeps what
// it has. A missing log (no `--debug`) leaves the cache empty. Never throws.
async function readLog($: any): Promise<LogCache | null> {
  try {
    const id = String(await $.session.id());
    let entry = logCache.get(id);
    if (!entry) {
      entry = { readAt: null, log: null, frozen: false, pending: null };
      logCache.set(id, entry);
    }
    const slot = entry;
    if (slot.frozen) return slot;
    if (slot.pending) {
      await slot.pending;
      return slot;
    }
    const now = Number(await $.clock.now());
    if (slot.readAt !== null && now - slot.readAt < LOG.minGapMs) return slot;
    slot.readAt = now;
    slot.pending = fetchLog($, id, slot);
    try {
      await slot.pending;
    } finally {
      slot.pending = null;
    }
    await recheckSuspects($, slot);
    return slot;
  } catch {
    return null;
  }
}

// enabledPlugins in key order, or undefined when settings give none.
async function enabledPlugins($: any): Promise<unknown> {
  try {
    const settings = await $.settings.read();
    return settings?.enabledPlugins;
  } catch {
    return undefined;
  }
}

// Copies the buffer to the snapshot the pane reads. `fresh` reads the
// settings again for the self-check names; a timed flush reuses the last.
// Disarms first, so a failure below never leaves the timer stuck.
async function flush($: any, fresh: boolean): Promise<void> {
  try {
    const buffer = await update($, bufferAtom, (b) => ({ ...b, armed: false }));
    if (!(await read($, paneOpenAtom))) return;
    const registry = await read($, registryAtom);
    const previous = await read($, snapshotAtom);
    const selfCheck =
      fresh || !previous
        ? selfCheckOf(
            await enabledPlugins($),
            registry.plugins,
            buffer.maxAbove,
          )
        : { ...previous.selfCheck, above: buffer.maxAbove };
    const at = Number(await $.clock.now());
    const log = fresh
      ? ((await readLog($))?.log ?? null)
      : (logCache.get(String(await $.session.id()))?.log ?? null);
    await update($, snapshotAtom, (s) =>
      snapshotOf(buffer, selfCheck, at, (s?.seq ?? 0) + 1, log),
    );
  } catch (err) {
    $.ui.log(
      `chain-inspector: refresh failed (${String((err as any)?.message ?? err)})`,
    );
  }
}

// Writes one record to the buffer and, with the pane open and no timer
// running, arms the one-second flush. A slowdown, or a suspect whose debug-log
// check is due, schedules `raise` on a zero-delay timer so the log read and the
// open stay off the dispatch's awaited path.
async function store($: any, record: TraceRecord): Promise<void> {
  const isOpen = await read($, paneOpenAtom);
  let arm = false;
  let slows: Slowdown[] = [];
  let due = null as Suspect | null;
  await update($, bufferAtom, (b) => {
    slows = slowdownsOf(b, record);
    const added = trackSuspect(addRecord(b, record), record);
    const suspect = added.suspects[record.key];
    due =
      suspect &&
      (suspect.checkedAt === null ||
        record.at - suspect.checkedAt >= TROUBLE.logRecheckMs)
        ? suspect
        : null;
    arm = isOpen && !b.armed;
    return arm ? { ...added, armed: true } : added;
  });
  if (arm) void $.clock.after(LIMITS.refreshMs, () => flush($, false));
  if (slows.length > 0 || due)
    void $.clock.after(0, () => raise($, record, slows, due));
}

// True when the engine's debug log for this session says `plugin` answered
// `event` without next(). The log exists only under `--debug`, so a missing or
// unreadable file answers false, and so does a frozen reader.
async function confirmedByLog(
  $: any,
  plugin: string,
  event: string,
): Promise<boolean> {
  const entry = await readLog($);
  if (!entry || entry.frozen || !entry.log) return false;
  return parsedNames(entry.log, plugin, event);
}

// With the pane open, reads the log again (inside the reader's rate limit) and
// redraws the snapshot. Runs on a zero-delay timer after `turn.complete`.
async function refreshLog($: any): Promise<void> {
  try {
    if (!(await read($, paneOpenAtom))) return;
    await readLog($);
    await flush($, false);
  } catch (err) {
    $.ui.log(
      `chain-inspector: log refresh failed (${String((err as any)?.message ?? err)})`,
    );
  }
}

// Turns a slowdown or a due suspect into trouble. A confirmed ender and a
// reported slowdown stay for the session. New trouble opens the pane.
async function raise(
  $: any,
  record: TraceRecord,
  slows: readonly Slowdown[],
  due: Suspect | null,
): Promise<void> {
  try {
    const at = Number(await $.clock.now());
    const found: TroubleItem[] = slows.map((s) => ({
      kind: "slow",
      plugin: s.plugin,
      key: s.key,
      event: s.event,
      at,
      sample: s.sample,
      mean: s.mean,
    }));
    if (due) {
      const known = (await read($, troubleAtom)).some(
        (t) =>
          t.kind === "ender" && t.key === due.key && t.plugin === due.plugin,
      );
      if (!known) {
        // The log names `ui.render` but not the component, so a mod that has
        // ended an owned component's chain cannot be told apart in it.
        const drawsOwn =
          due.event === "ui.render" &&
          ((await read($, bufferAtom)).ownedEnders ?? []).includes(due.plugin);
        const named =
          !drawsOwn && (await confirmedByLog($, due.plugin, due.event));
        await update($, bufferAtom, (b) => {
          const now = b.suspects[due.key];
          return now && now.plugin === due.plugin
            ? {
                ...b,
                suspects: {
                  ...b.suspects,
                  [due.key]: { ...now, checkedAt: at },
                },
              }
            : b;
        });
        if (named)
          found.push({
            kind: "ender",
            plugin: due.plugin,
            key: due.key,
            event: due.event,
            at,
          });
      }
    }
    if (found.length === 0) return;
    let fresh: TroubleItem[] = [];
    await update($, troubleAtom, (t) => {
      fresh = found.filter((f) => !t.some((x) => sameTrouble(x, f)));
      return fresh.length > 0 ? [...t, ...fresh] : t;
    });
    const newest = fresh[fresh.length - 1];
    if (newest) await announce($, newest);
  } catch (err) {
    $.ui.log(
      `chain-inspector: trouble check failed for ${record.key} (${String((err as any)?.message ?? err)})`,
    );
  }
}

// Opens the pane without being asked. When the engine cannot place it, the PromptHint line carries a note until the owner opens the pane.
async function announce($: any, item: TroubleItem): Promise<void> {
  let placed = false;
  let asked = false;
  try {
    const opened = await $.ui.open({
      id: "chain-inspector",
      title: "chain",
      closeOnEscape: true,
    });
    asked = true;
    placed = opened.isPlaced === true;
  } catch {
    // No surface is attached (a headless run), so only the hint can speak.
  }
  if (asked) {
    await update($, paneOpenAtom, () => true);
    await flush($, true);
  }
  await update($, hintTailAtom, () => (placed ? null : hintTextOf(item)));
}

// A render dispatch is pure, and the engine refuses a state write made while
// one runs. A `ui.render` record is therefore written from a zero-delay timer,
// which runs after the dispatch has returned.
async function noteTrace(
  $: any,
  event: string,
  key: string,
  trace: readonly any[],
  failed: boolean,
): Promise<void> {
  // The engine lists no link of the inspector's own beneath its star hook, so
  // a dispatch the inspector answers itself (`/chain`) has an empty trace and
  // nothing to show.
  if (trace.length === 0 && !failed) return;
  const at = Number(await $.clock.now());
  const record = makeRecord(event, key, at, trace, failed);
  const later = () =>
    void $.clock.after(0, async () => {
      try {
        await store($, record);
      } catch (err) {
        $.ui.log(
          `chain-inspector: record lost (${String((err as any)?.message ?? err)})`,
        );
      }
    });
  if (event === "ui.render") return later();
  try {
    await store($, record);
  } catch {
    later();
  }
}

export const register: Register = (on) => {
  logCache.clear();

  // The one star hook. An untraced dispatch goes straight to `next(e)`. A
  // traced one runs `next(e)`, reads `next.trace`, then returns the result
  // unchanged, or rethrows the rejection after recording it.
  on("*", async ($, e, next) => {
    const event = next.event;
    if (isEngineCall(event)) return next(e);
    let key: string = event;
    if (next.is("ui.render", e)) {
      if (e.requestId === "chain-inspector") return next(e);
      key = keyOf(event, { component: e.component, requestId: e.requestId });
    } else if (next.is("tool.call", e)) {
      key = keyOf(event, { tool: e.tool });
    }
    const registry = await read($, registryAtom);
    if (!isTraced(registry.traced, event)) return next(e);
    if (!(await read($, tracingAtom))) return next(e);

    let result: unknown;
    let failure: unknown;
    let failed = false;
    try {
      result = await next(e);
    } catch (err) {
      failed = true;
      failure = err;
    }
    try {
      await noteTrace($, event, key, next.trace, failed);
    } catch {
      // Recording never changes what the dispatch returns.
    }
    if (failed) throw failure;
    return result;
  });

  // Judges every mod loaded after this one and never refuses it.
  on("plugin.register", async ($, e, next) => {
    try {
      const record = {
        name: e.name,
        tier: e.tier,
        provenance: e.provenance,
        events: [...e.uses.events],
      };
      await update($, registryAtom, (r) => addPlugin(r, record));
    } catch {
      // A failed note leaves the mod unlisted and still loads it.
    }
    return next(e);
  });

  on("session.start", async ($, e, next) => {
    try {
      await $.command.register({
        name: "chain",
        description: "hook chain inspector",
        argumentHint: "[open|on|off]",
      });
    } catch (err) {
      $.ui.log(
        `chain-inspector: /chain not registered (${String((err as any)?.message ?? err)})`,
      );
    }
    return next(e);
  });

  // A finished turn refreshes the log readings while the pane is open. The
  // read runs on a timer, off the dispatch's path.
  on("turn.complete", async ($, e, next) => {
    void $.clock.after(0, () => refreshLog($));
    return next(e);
  });

  on("command.run", { command: "chain" }, async ($, e) => {
    try {
      const arg = (e.args ?? "").trim().split(/\s+/)[0] ?? "";
      switch (arg) {
        case "":
        case "open": {
          const opened = await $.ui.open({
            id: "chain-inspector",
            title: "chain",
            closeOnEscape: true,
          });
          await update($, paneOpenAtom, () => true);
          await flush($, true);
          const registry = await read($, registryAtom);
          if (!opened.isPlaced)
            return { text: "chain inspector waits for a wider terminal" };
          await update($, hintTailAtom, () => null);
          return {
            text: `chain inspector opened · ${registry.plugins.length} mods traced`,
          };
        }
        case "off":
          await update($, tracingAtom, () => false);
          return { text: "chain inspector: tracing off" };
        case "on":
          await update($, tracingAtom, () => true);
          return { text: "chain inspector: tracing on" };
        default:
          return { text: USAGE };
      }
    } catch (err) {
      return {
        text: `chain inspector: ${String((err as any)?.message ?? err)}`,
      };
    }
  });

  // Escape, as the person's close, steps back from a row's detail first and
  // closes the pane on the next press. Any other close ends the pane.
  on("ui.close", { id: "chain-inspector" }, async ($, e, next) => {
    const detail = (await read($, selectedAtom)) !== null;
    if (e.origin.kind === "person" && detail) {
      await update($, selectedAtom, () => null);
      return { value: undefined };
    }
    await update($, paneOpenAtom, () => false);
    await update($, selectedAtom, () => null);
    return next(e);
  });

  // Pressing a row opens its detail, and pressing it again returns.
  on(
    "ui.press",
    { requestId: "chain-inspector", element: /^row-/ },
    async ($, e, next) => {
      const key = e.element.slice(ROW_PREFIX.length);
      await update($, selectedAtom, (now) => (now === key ? null : key));
      return next(e);
    },
  );

  on(
    "ui.render",
    { component: "Pane", requestId: "chain-inspector" },
    async ($, e) =>
      pane({
        table: $.ui.resolve(e),
        columns: e.props.bodyColumns,
        snapshot: await read($, snapshotAtom),
        pluginCount: (await read($, registryAtom)).plugins.length,
        tracing: await read($, tracingAtom),
        selected: await read($, selectedAtom),
        trouble: await read($, troubleAtom),
        logStatus: await read($, logStatusAtom),
      }),
  );

  // Adds the trouble note to the engine's own hint line and leaves the rest of
  // the line as it is. Reads only.
  on("ui.render", { component: "PromptHint" }, async ($, e, next) => {
    const tail = await read($, hintTailAtom);
    if (!tail) return next(e);
    return next({ ...e, props: { ...e.props, tail } });
  });
};

