import type { BuiltinSample, CommandHook, ParsedLog } from "./types/index";

// Pure. Turns the engine's debug log into the three results the pane uses: the
// enders it names, the builtin timings and the command hooks. No IO.

// Tuning knobs of the log reader.
export const LOG = Object.freeze({
  // Reads of the debug log are at least this far apart.
  minGapMs: 5000,
  // A log over this many bytes freezes readings for the session.
  maxBytes: 4 * 1024 * 1024,
});

export const FROZEN_LINE = "debug log over 4 MiB · log readings frozen";

const BUILTIN_PREFIX = "cc-plugin-";

const ENDER = /(?:^|\s)(\S+) \([^)]*\) answered (\S+) without next\(\)/;
const BUILTIN = /hooks module (\S+)@builtin (\S+) settled in (\d+(?:\.\d+)?)ms/;
const HOOK =
  /Hooks: (\S+) \[(.*?)\](?: \(plugin ([^)]+)\))? finished with status (-?\d+) \((\d+(?:\.\d+)?)ms\)/;

// Extensions that mark a token as a script.
const SCRIPT_EXT = /\.(py|sh|ps1|mjs|js|cmd|bat|ts)$/i;

// A file name with nothing else in it.
const PLAIN_NAME = /^[A-Za-z0-9._-]+$/;

// Shown when the command holds no plain script file name.
export const GENERIC_SCRIPT = "command";

const lastSegment = (path: string) => path.split(/[\\/]/).pop() ?? path;

const plainScript = (path: string): string | null => {
  const name = lastSegment(path);
  return PLAIN_NAME.test(name) && SCRIPT_EXT.test(name) ? name : null;
};

// The script's file name in a hook command, shown only when it is a plain file
// name with a script extension. Anything else gives `command`, so the rest of
// the command, which can hold paths and arguments, never reaches the screen. A
// `run-hook` wrapper gives way to the script it runs when that is plain too.
export function scriptNameOf(command: string): string {
  const tokens = [...command.matchAll(/"([^"]*)"|(\S+)/g)].map(
    (m) => m[1] ?? m[2] ?? "",
  );
  const first = tokens.find((t) => SCRIPT_EXT.test(t));
  if (first === undefined) return GENERIC_SCRIPT;
  const name = plainScript(first);
  if (name !== null && /^run-hook\./i.test(name)) {
    const after = tokens[tokens.indexOf(first) + 1];
    const target = after === undefined ? null : plainScript(after);
    if (target !== null) return target;
  }
  return name ?? GENERIC_SCRIPT;
}

const STAMP = /^(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?Z)/;

// `foundry@personal` -> `foundry`.
const pluginName = (name: string) => name.split("@")[0] ?? name;

// Stamp step (1 ms) plus rounding of the two logged ms values (0.1 ms).
const NEST_TOLERANCE_MS = 1.1;

export function parseLog(text: string): ParsedLog {
  const enders = new Set<string>();
  // The latest dispatch of each event, builtins in settle order (innermost
  // first).
  const dispatches = new Map<string, BuiltinSample[]>();
  // Start time (timestamp minus ms) of the latest line of each event.
  const starts = new Map<string, number>();
  const hooks = new Map<string, CommandHook>();
  for (const line of text.split("\n")) {
    if (line.includes("answered")) {
      const m = ENDER.exec(line);
      if (m) enders.add(`${m[1]} ${m[2]}`);
    }
    if (line.includes("@builtin ")) {
      const m = BUILTIN.exec(line);
      if (m) {
        const name = (m[1] as string).startsWith(BUILTIN_PREFIX)
          ? (m[1] as string).slice(BUILTIN_PREFIX.length)
          : (m[1] as string);
        const event = m[2] as string;
        const ms = Number(m[3]);
        const group = dispatches.get(event);
        const prev = group?.[group.length - 1];
        const stamp = STAMP.exec(line);
        const start =
          (stamp ? Date.parse(stamp[1] as string) : Number.NaN) - ms;
        const prevStart = starts.get(event);
        // A line nests around the group before it when it started within
        // 1.1 ms after that group's latest start (1 ms stamp step plus 0.1 ms
        // for the two rounded ms values) and no builtin of its name is in the
        // group. A line with no readable stamp nests on the name rule alone.
        const nested =
          group !== undefined &&
          prev !== undefined &&
          !group.some((b) => b.name === name) &&
          (prevStart !== undefined &&
          Number.isFinite(start) &&
          Number.isFinite(prevStart)
            ? start <= prevStart + NEST_TOLERANCE_MS
            : true);
        starts.set(event, start);
        const sample: BuiltinSample = {
          name,
          event,
          ms,
          ownMs: Math.max(0, ms - (nested && prev ? prev.ms : 0)),
        };
        if (nested && group) group.push(sample);
        else dispatches.set(event, [sample]);
      }
    }
    if (line.includes("Hooks: ")) {
      const m = HOOK.exec(line);
      if (m) {
        const [event, ...rest] = (m[1] as string).split(":");
        const matcher = rest.length > 0 ? rest.join(":") : null;
        const source = m[3] ? pluginName(m[3]) : "settings";
        const script = scriptNameOf(m[2] as string);
        const key = `${m[1]}|${source}|${script}`;
        hooks.set(key, {
          event: event as string,
          matcher,
          source,
          script,
          ms: Number(m[5]),
          runs: (hooks.get(key)?.runs ?? 0) + 1,
          status: Number(m[4]),
        });
      }
    }
  }
  return {
    enders: [...enders],
    builtins: [...dispatches.values()].flat(),
    hooks: [...hooks.values()].sort((a, b) => b.ms - a.ms),
  };
}

// True when the parsed log has a line saying `plugin` answered `event` without
// calling next().
export function parsedNames(
  log: ParsedLog,
  plugin: string,
  event: string,
): boolean {
  return log.enders.includes(`${plugin} ${event}`);
}

