import type { PluginRecord, SelfCheck } from "./types/index";

// Pure. Works out what sits above the inspector, where it cannot see. Two
// signals: the links above it in a trace, and the enabled plugins keyed ahead
// of it that it never judged.

export const SELF_NAME = "chain-inspector";

// A trace lists the links beneath the caller, so its first index minus one is
// the caller's own place, which equals the number of links above it.
export function linksAbove(links: readonly { index: number }[]): number {
  const first = links[0];
  if (!first) return 0;
  return Math.max(0, first.index - 1);
}

// `name@marketplace` to `name`.
export function bareName(key: string): string {
  const at = key.lastIndexOf("@");
  return at > 0 ? key.slice(0, at) : key;
}

// The enabled plugins keyed before the inspector that it never judged, in key
// order. Null when `enabled` is not an object, so the names are unknown.
export function namesBefore(
  enabled: unknown,
  judged: readonly PluginRecord[],
): string[] | null {
  if (typeof enabled !== "object" || enabled === null || Array.isArray(enabled))
    return null;
  const keys = Object.keys(enabled);
  const self = keys.findIndex((k) => bareName(k) === SELF_NAME);
  if (self < 0) return [];
  const seen = new Set<string>();
  for (const p of judged) {
    seen.add(p.name);
    seen.add(p.provenance);
  }
  const names: string[] = [];
  for (const key of keys.slice(0, self)) {
    if ((enabled as Record<string, unknown>)[key] === false) continue;
    if (seen.has(key) || seen.has(bareName(key))) continue;
    names.push(bareName(key));
  }
  return names;
}

export function selfCheckOf(
  enabled: unknown,
  judged: readonly PluginRecord[],
  above: number,
): SelfCheck {
  const names = namesBefore(enabled, judged);
  return { above, names: names ?? [], namesKnown: names !== null };
}

const plural = (n: number, one: string, many: string) => (n === 1 ? one : many);

// The pane header's line, or null when nothing sits above the inspector.
export function selfCheckLine(sc: SelfCheck): string | null {
  const n = sc.names.length;
  if (n > 0) {
    const verb = plural(n, "loads", "load");
    const be = plural(n, "is", "are");
    const head = `${n} ${plural(n, "mod", "mods")} ${verb} before the inspector and ${be} not traced: ${sc.names.join(", ")}`;
    return sc.above > 0
      ? `${head} · ${sc.above} ${plural(sc.above, "link", "links")} above`
      : head;
  }
  if (sc.above > 0) {
    const links = plural(sc.above, "link", "links");
    const verb = plural(sc.above, "sits", "sit");
    const be = plural(sc.above, "is", "are");
    const tail = sc.namesKnown ? "" : " (names unavailable)";
    return `${sc.above} ${links} ${verb} above the inspector and ${be} not traced${tail}`;
  }
  return null;
}

