import { linksAbove } from "./selfcheck";
import type {
  Aggregate,
  BuiltinSample,
  LinkRecord,
  ParsedLog,
  PluginRecord,
  Registry,
  Slowdown,
  Snapshot,
  SnapshotRow,
  TraceBuffer,
  TraceRecord,
  TroubleItem,
} from "./types/index";

// Pure. The record shape, the ring buffer, the per-link aggregates, the event
// keys and the traced-event test. No IO and no state.

// Tuning knobs. Everything the star hook and the pane tune on sits here.
export const LIMITS = Object.freeze({
  // Records kept per key.
  perKey: 20,
  // Keys kept. The least recently dispatched key goes first.
  maxKeys: 64,
  // Records the detail view lists.
  detail: 5,
  // The pane redraws at most this often.
  refreshMs: 1000,
});

// Tuning knobs of the trouble rules.
export const TROUBLE = Object.freeze({
  // Short records in a row, all ending at one mod, that make it a suspect.
  shortRun: 3,
  // Timed samples a mod needs on a key before a slowdown can alarm.
  slowSamples: 10,
  // A new sample over this many times the earlier mean is a slowdown.
  slowFactor: 2,
  // A sample under this many ms is no trouble, however much it grew. Matches
  // the ms at which the pane turns a link warn.
  slowMinMs: 20,
  // A suspect's debug-log check repeats no sooner than this.
  logRecheckMs: 5000,
});

// `ui.render` components where one mod ending the chain starves the others.
// Every other component is drawn by its owner, so a mod that ends its chain
// is drawing it, by design.
export const SHARED_COMPONENTS = Object.freeze([
  "AbovePrompt",
  "PromptHint",
  "SessionMode",
  "Spinner",
]);

export const PANE_ID = "chain-inspector";

// Events the star hook never traces, so it passes them with no state read.
// `engine.create` runs before `$` exists. `state.*` is how the inspector keeps
// its own records. The rest are engine calls that fire in bursts of hundreds
// at startup: a headless "ok" turn dispatched 300 `ui.resolve`, 276
// `tool.describe`, 238 `command.describe` and 140 `env.get` (W-0012 C4, and a
// probe above the inspector on 2026-10-13). A state read per dispatch queued
// behind that burst and cost the inspector 30 ms to 110 ms on each.
export const ENGINE_CALLS = Object.freeze({
  exact: Object.freeze([
    "engine.create",
    "ui.resolve",
    "ui.invalidate",
    "ui.status",
    "tool.describe",
    "command.describe",
    "agent.offer",
    "prompt.section",
    "prompt.attachment",
    "session.append",
    // The inspector's own debug-log read, so it never records itself.
    "fs.read",
    "fs.stat",
    "session.id",
  ]),
  prefix: Object.freeze(["state.", "clock.", "store.", "env."]),
});

// Streaming events hand back a stream, not a promise, so they pass untraced.
export const STREAMING = Object.freeze(["turn.step", "process.spawn"]);

// Traced whether or not a mod says it hooks it.
export const ALWAYS_TRACED = Object.freeze(["ui.render"]);

export function isEngineCall(event: string): boolean {
  return (
    ENGINE_CALLS.exact.includes(event) ||
    ENGINE_CALLS.prefix.some((p) => event.startsWith(p)) ||
    STREAMING.includes(event)
  );
}

// A pattern a mod hooks, as `uses.events` writes it. The bare `*` and the
// negations name nearly every event, so they widen nothing here.
export function isTracePattern(pattern: string): boolean {
  return pattern !== "*" && !pattern.startsWith("!");
}

function matches(pattern: string, event: string): boolean {
  if (!pattern.includes("*")) return pattern === event;
  const source = pattern
    .split("*")
    .map((part) => part.replace(/[.+?^${}()|[\]\\]/g, "\\$&"))
    .join(".*");
  return new RegExp(`^${source}$`).test(event);
}

export function isTraced(patterns: readonly string[], event: string): boolean {
  if (isEngineCall(event)) return false;
  return (
    ALWAYS_TRACED.includes(event) || patterns.some((p) => matches(p, event))
  );
}

export function emptyRegistry(): Registry {
  return { plugins: [], traced: [] };
}

// Stores one judged mod. A mod seen twice replaces its earlier entry.
export function addPlugin(registry: Registry, plugin: PluginRecord): Registry {
  const plugins = [
    ...registry.plugins.filter(
      (p) => !(p.name === plugin.name && p.provenance === plugin.provenance),
    ),
    plugin,
  ];
  const traced: string[] = [];
  for (const p of plugins)
    for (const pattern of p.events)
      if (isTracePattern(pattern) && !traced.includes(pattern))
        traced.push(pattern);
  return { plugins, traced };
}

export function emptyBuffer(): TraceBuffer {
  return {
    total: 0,
    armed: false,
    maxAbove: 0,
    order: [],
    records: {},
    aggregates: {},
    suspects: {},
    ownedEnders: [],
  };
}

// The row key of a dispatch. Only a pane keeps its requestId: the others name
// one message or tool use each, which would grow the keys without bound.
export function keyOf(
  event: string,
  detail: { component?: string; requestId?: string; tool?: string },
): string {
  if (event === "ui.render") {
    const component = detail.component ?? "ui.render";
    return component === "Pane" && detail.requestId
      ? `Pane:${detail.requestId}`
      : component;
  }
  if (event === "tool.call" && detail.tool) return `tool.call:${detail.tool}`;
  return event;
}

type TraceEntryLike = {
  index?: unknown;
  plugin?: unknown;
  tier?: unknown;
  outcome?: unknown;
  ms?: unknown;
};

const finite = (n: unknown): number =>
  typeof n === "number" && Number.isFinite(n) ? n : 0;

// Keeps the five fields of each entry and nothing else. `received` and
// `returned` can hold whole prompts, so they are never read.
export function linksOf(trace: readonly TraceEntryLike[]): LinkRecord[] {
  return trace.map((t) => ({
    index: finite(t.index),
    plugin: String(t.plugin ?? ""),
    tier: String(t.tier ?? ""),
    outcome: String(t.outcome ?? ""),
    ms: finite(t.ms),
  }));
}

export function makeRecord(
  event: string,
  key: string,
  at: number,
  trace: readonly TraceEntryLike[],
  rejected: boolean,
): TraceRecord {
  const links = linksOf(trace);
  const last = links[links.length - 1];
  return {
    event,
    key,
    at,
    links,
    endsAtEngine: last !== undefined && last.plugin === "engine",
    rejected,
  };
}

// A plugin's cost on one dispatch: the sum over its links.
function costs(links: readonly LinkRecord[]): Map<string, number> {
  const byPlugin = new Map<string, number>();
  for (const l of links)
    byPlugin.set(l.plugin, (byPlugin.get(l.plugin) ?? 0) + l.ms);
  return byPlugin;
}

function fold(agg: Aggregate | undefined, ms: number): Aggregate {
  const count = (agg?.count ?? 0) + 1;
  const mean = (agg?.meanMs ?? 0) + (ms - (agg?.meanMs ?? 0)) / count;
  return { count, meanMs: mean, maxMs: Math.max(agg?.maxMs ?? 0, ms) };
}

// Adds one record: the ring buffer keeps the last `perKey`, the aggregates
// fold in each plugin's cost, and the least recently dispatched key goes once
// there are more than `maxKeys`. Returns a new buffer.
export function addRecord(
  buffer: TraceBuffer,
  record: TraceRecord,
): TraceBuffer {
  const key = record.key;
  const records = {
    ...buffer.records,
    [key]: [...(buffer.records[key] ?? []), record].slice(-LIMITS.perKey),
  };
  const aggregates = { ...buffer.aggregates };
  const perPlugin = { ...(aggregates[key] ?? {}) };
  for (const [plugin, ms] of costs(record.links))
    perPlugin[plugin] = fold(perPlugin[plugin], ms);
  aggregates[key] = perPlugin;
  const suspects = { ...buffer.suspects };
  const order = [...buffer.order.filter((k) => k !== key), key];
  while (order.length > LIMITS.maxKeys) {
    const gone = order.shift() as string;
    delete records[gone];
    delete aggregates[gone];
    delete suspects[gone];
  }
  return {
    ...buffer,
    total: buffer.total + 1,
    maxAbove: Math.max(buffer.maxAbove, linksAbove(record.links)),
    order,
    records,
    aggregates,
    suspects,
  };
}

// The chain of a record in order, one entry per plugin. A plugin with two
// hooks on the event shows once, at its first place.
export function chainOf(record: TraceRecord): string[] {
  const seen: string[] = [];
  for (const l of [...record.links].sort((a, b) => a.index - b.index))
    if (!seen.includes(l.plugin)) seen.push(l.plugin);
  return seen;
}

// Replaces the `engine` entry of a chain with the builtins seen on `event`,
// each at its own time, then `engine` with its time minus the outermost
// builtin's logged ms (the last one settled). A chain with no `engine` entry,
// or an event with no builtin, comes back as it was.
export function withBuiltins(
  chain: SnapshotRow["chain"],
  event: string,
  builtins: readonly BuiltinSample[],
): SnapshotRow["chain"] {
  const mine = builtins.filter((b) => b.event === event);
  if (mine.length === 0 || !chain.some((l) => l.plugin === "engine"))
    return chain;
  const spent = mine[mine.length - 1]?.ms ?? 0;
  return chain.flatMap((link) =>
    link.plugin === "engine"
      ? [
          ...mine.map((b) => ({
            plugin: b.name,
            tier: "builtin",
            meanMs: b.ownMs,
            maxMs: b.ownMs,
            count: 1,
            builtin: true,
          })),
          {
            ...link,
            meanMs: Math.max(0, link.meanMs - spent),
            maxMs: Math.max(0, link.maxMs - spent),
          },
        ]
      : [link],
  );
}

// One row per key, most recently dispatched first. A row's chain is the
// newest record's, each link carrying its running mean and max. `builtins` are
// the log's builtin timings, folded out of the engine entry.
export function rowsOf(
  buffer: TraceBuffer,
  builtins: readonly BuiltinSample[] = [],
): SnapshotRow[] {
  const rows: SnapshotRow[] = [];
  for (const key of [...buffer.order].reverse()) {
    const recent = [...(buffer.records[key] ?? [])].reverse();
    const newest = recent[0];
    if (!newest) continue;
    const firstTier = new Map<string, string>();
    for (const l of newest.links)
      if (!firstTier.has(l.plugin)) firstTier.set(l.plugin, l.tier);
    const agg = buffer.aggregates[key] ?? {};
    rows.push({
      key,
      event: newest.event,
      chain: withBuiltins(
        chainOf(newest).map((plugin) => ({
          plugin,
          tier: firstTier.get(plugin) ?? "",
          meanMs: agg[plugin]?.meanMs ?? 0,
          maxMs: agg[plugin]?.maxMs ?? 0,
          count: agg[plugin]?.count ?? 0,
        })),
        newest.event,
        builtins,
      ),
      endsAtEngine: newest.endsAtEngine,
      recent: recent.slice(0, LIMITS.detail),
    });
  }
  return rows;
}

export function snapshotOf(
  buffer: TraceBuffer,
  selfCheck: Snapshot["selfCheck"],
  at: number,
  seq: number,
  log: ParsedLog | null = null,
): Snapshot {
  return {
    seq,
    at,
    rows: rowsOf(buffer, log?.builtins ?? []),
    selfCheck,
    suspects: Object.values(buffer.suspects),
    ...(log ? { commandHooks: log.hooks } : {}),
  };
}

// --- trouble -----------------------------------------------------------------

// Events whose owning mod answers without next(), by design.
const OWNED_EVENTS = Object.freeze([
  "command.run",
  "tool.call",
  "ui.press",
  "ui.open",
  "ui.close",
]);

// True when ending this event's chain starves other mods. Every event is
// shared except those in OWNED_EVENTS, which their owner answers. A
// `ui.render` key is shared only for the components in SHARED_COMPONENTS.
export function isSharedSurface(event: string, key: string): boolean {
  if (OWNED_EVENTS.includes(event)) return false;
  return event !== "ui.render" || SHARED_COMPONENTS.includes(key);
}

// Remembers a mod that ended the chain of an owned `ui.render` component.
function noteOwnedEnd(buffer: TraceBuffer, record: TraceRecord): TraceBuffer {
  const last = record.links[record.links.length - 1];
  const known = buffer.ownedEnders ?? [];
  if (
    record.event !== "ui.render" ||
    record.endsAtEngine ||
    record.rejected ||
    !last ||
    known.includes(last.plugin)
  )
    return buffer;
  return { ...buffer, ownedEnders: [...known, last.plugin] };
}

// The mod that ended the last `shortRun` records of a key, or null. A record
// is short when its chain stops short of the engine; a rejected record never
// counts.
export function endingMod(records: readonly TraceRecord[]): string | null {
  if (records.length < TROUBLE.shortRun) return null;
  let who: string | null = null;
  for (const r of records.slice(-TROUBLE.shortRun)) {
    const last = r.links[r.links.length - 1];
    if (r.endsAtEngine || r.rejected || !last) return null;
    if (who !== null && who !== last.plugin) return null;
    who = last.plugin;
  }
  return who;
}

// Updates the key's suspect after `record` joined the buffer: a run of short
// records ending at one mod sets it, and any other newest history clears it.
export function trackSuspect(
  buffer: TraceBuffer,
  record: TraceRecord,
): TraceBuffer {
  if (!isSharedSurface(record.event, record.key))
    return noteOwnedEnd(buffer, record);
  const key = record.key;
  const who = endingMod(buffer.records[key] ?? []);
  const prior = buffer.suspects[key];
  if (who === null) {
    if (!prior) return buffer;
    const suspects = { ...buffer.suspects };
    delete suspects[key];
    return { ...buffer, suspects };
  }
  return {
    ...buffer,
    suspects: {
      ...buffer.suspects,
      [key]: {
        key,
        event: record.event,
        plugin: who,
        checkedAt: prior && prior.plugin === who ? prior.checkedAt : null,
      },
    },
  };
}

// Plugins whose cost on `record` is over `slowFactor` times their mean on the
// earlier records of the key. Reads the buffer as it stood before `record`
// joined it. The engine's own entry is never a slowdown.
export function slowdownsOf(
  before: TraceBuffer,
  record: TraceRecord,
): Slowdown[] {
  const found: Slowdown[] = [];
  for (const [plugin, ms] of costs(record.links)) {
    if (plugin === "engine") continue;
    const agg = before.aggregates[record.key]?.[plugin];
    if (!agg || agg.count < TROUBLE.slowSamples) continue;
    if (ms < TROUBLE.slowMinMs || ms <= TROUBLE.slowFactor * agg.meanMs)
      continue;
    found.push({
      plugin,
      key: record.key,
      event: record.event,
      sample: ms,
      mean: agg.meanMs,
    });
  }
  return found;
}

const escapeRe = (text: string) => text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// True when the engine's debug log has a line saying `plugin` answered `event`
// without calling next().
export function logNames(log: string, plugin: string, event: string): boolean {
  const who = escapeRe(plugin);
  const what = escapeRe(event);
  return new RegExp(
    `(^|\\s)${who} \\([^)]*\\) answered ${what} without next\\(\\)`,
    "m",
  ).test(log);
}

export function sameTrouble(a: TroubleItem, b: TroubleItem): boolean {
  return a.kind === b.kind && a.key === b.key && a.plugin === b.plugin;
}

// The note on the hint line for one trouble item.
export function hintTextOf(item: TroubleItem): string {
  return item.kind === "ender"
    ? `chain: ${item.plugin} ended ${item.key} · /chain`
    : `chain: ${item.plugin} slow on ${item.key} · /chain`;
}

