import { selfCheckLine } from "../selfcheck";
import { FROZEN_LINE } from "../logparse";
import type {
  LogStatus,
  Snapshot,
  SnapshotRow,
  TroubleItem,
} from "../types/index";
import { paint, type ToneName } from "./theme";

// The chain inspector pane. Pure: state and props in, a tree out. Text takes
// single-width glyphs only, so a string's length is its width in cells.

export const ROW_PREFIX = "row-";

// Mean ms at which a link turns warn, then bad.
export const SLOW_MS = Object.freeze({ warn: 20, bad: 100 });

export type Seg = {
  text: string;
  tone?: ToneName;
  bold?: boolean;
  dim?: boolean;
  // The Button key when the segment is pressable.
  press?: string;
};

export type Line = { key: string; segs: Seg[] };

export type PaneInput = {
  snapshot: Snapshot | null;
  pluginCount: number;
  tracing: boolean;
  selected: string | null;
  columns: number;
  // Confirmed enders and slowdowns.
  trouble: TroubleItem[];
  // Left out, the pane draws as it does with no debug log read.
  logStatus?: LogStatus;
};

// What the engine entry reads as when no debug log can split the builtins out.
export const ENGINE_LABEL = "engine + builtins";

export const SEPARATOR = " › ";

export function fmtMs(ms: number): string {
  if (ms >= 1000) return `${(ms / 1000).toFixed(1)}s`;
  if (ms >= 10) return String(Math.round(ms));
  return ms.toFixed(1);
}

function msTone(ms: number): ToneName {
  if (ms >= SLOW_MS.bad) return "bad";
  if (ms >= SLOW_MS.warn) return "warn";
  return "muted";
}

const widthOf = (segs: Seg[]) => segs.reduce((n, s) => n + s.text.length, 0);

// Cuts the end of a line so it fits, closing with an ellipsis.
export function fit(segs: Seg[], columns: number): Seg[] {
  if (widthOf(segs) <= columns) return segs;
  const out: Seg[] = [];
  let room = Math.max(0, columns - 1);
  for (const s of segs) {
    if (room <= 0) break;
    const text = s.text.length <= room ? s.text : s.text.slice(0, room);
    out.push({ ...s, text });
    room -= text.length;
  }
  out.push({ text: "…", tone: "comment" });
  return out;
}

// Breaks a sentence at spaces into lines of at most `columns` cells.
export function wrap(text: string, columns: number): string[] {
  const lines: string[] = [];
  let line = "";
  for (const word of text.split(" ")) {
    const next = line === "" ? word : `${line} ${word}`;
    if (next.length <= columns || line === "") line = next;
    else {
      lines.push(line);
      line = word;
    }
  }
  if (line !== "") lines.push(line);
  return lines.map((l) => (l.length > columns ? l.slice(0, columns) : l));
}

// `event  mod 2.1ms › mod 0.4 › engine 1.0`. The first link carries the unit.
export function rowSegs(row: SnapshotRow, engine = "engine"): Seg[] {
  const segs: Seg[] = [
    { text: row.key, tone: "accent", bold: true, press: ROW_PREFIX + row.key },
    { text: "  " },
  ];
  row.chain.forEach((link, i) => {
    if (i > 0) segs.push({ text: SEPARATOR, tone: "comment" });
    const isEngine = link.plugin === "engine";
    const dim = isEngine || link.builtin === true;
    segs.push({
      text: isEngine ? engine : link.plugin,
      tone: dim ? "muted" : "fg",
      dim,
    });
    segs.push({
      text: ` ${fmtMs(link.meanMs)}${i === 0 ? "ms" : ""}`,
      tone: msTone(link.meanMs),
    });
  });
  return segs;
}

function ageLabel(snapshot: Snapshot, at: number): string {
  const s = Math.max(0, Math.round((snapshot.at - at) / 1000));
  return `${s}s ago`;
}

function header(input: PaneInput): Line[] {
  const n = input.pluginCount;
  const lines: Line[] = [
    {
      key: "title",
      segs: fit(
        [
          { text: "chain inspector", tone: "accent", bold: true },
          {
            text: ` · ${n} ${n === 1 ? "mod" : "mods"} traced · `,
            tone: "muted",
          },
          input.tracing
            ? { text: "tracing on", tone: "ok" }
            : { text: "tracing off", tone: "warn", bold: true },
        ],
        input.columns,
      ),
    },
  ];
  if (input.logStatus === "frozen")
    lines.push({
      key: "frozen",
      segs: fit(
        [{ text: FROZEN_LINE, tone: "muted", dim: true }],
        input.columns,
      ),
    });
  const check = input.snapshot ? selfCheckLine(input.snapshot.selfCheck) : null;
  if (check)
    wrap(check, input.columns).forEach((text, i) =>
      lines.push({ key: `check-${i}`, segs: [{ text, tone: "warn" }] }),
    );
  return lines;
}

// The trouble section: a red row per confirmed ender, a warn row per suspected
// ender and per slowdown. Empty when there is no trouble. A suspect already
// confirmed shows once, as confirmed.
export function troubleLines(input: PaneInput): Line[] {
  const confirmed = input.trouble.filter((t) => t.kind === "ender");
  const suspects = (input.snapshot?.suspects ?? []).filter(
    (s) => !confirmed.some((t) => t.key === s.key && t.plugin === s.plugin),
  );
  const slow = input.trouble.filter((t) => t.kind === "slow");
  if (confirmed.length + suspects.length + slow.length === 0) return [];
  const row = (key: string, tone: ToneName, text: string): Line => ({
    key,
    segs: fit([{ text, tone, bold: tone === "bad" }], input.columns),
  });
  return [
    row("trouble-head", "bad", "trouble"),
    ...confirmed.map((t) =>
      row(
        `trouble-end-${t.key}-${t.plugin}`,
        "bad",
        `✗ ${t.plugin} ended ${t.key} · confirmed`,
      ),
    ),
    ...suspects.map((s) =>
      row(
        `trouble-sus-${s.key}-${s.plugin}`,
        "warn",
        `! ${s.plugin} may have ended ${s.key} · suspected`,
      ),
    ),
    ...slow.map((t) =>
      row(
        `trouble-slow-${t.key}-${t.plugin}`,
        "warn",
        `~ ${t.plugin} slow on ${t.key} · ${fmtMs(t.sample ?? 0)}ms vs ${fmtMs(t.mean ?? 0)}ms mean`,
      ),
    ),
  ];
}

// The command hooks section: one row per hook, slowest first, from the debug
// log. Empty when the log gave none. A non-zero status turns the row bad.
export function commandHookLines(input: PaneInput): Line[] {
  const hooks = input.snapshot?.commandHooks ?? [];
  if (hooks.length === 0) return [];
  return [
    {
      key: "hooks-head",
      segs: fit(
        [{ text: "command hooks", tone: "accent", bold: true }],
        input.columns,
      ),
    },
    ...hooks.map((h, i): Line => {
      const failed = h.status !== 0;
      return {
        key: `hook-${i}`,
        segs: fit(
          [
            {
              text: h.matcher ? `${h.event}:${h.matcher}` : h.event,
              tone: "fg",
            },
            { text: `  ${h.source}  `, tone: "muted" },
            { text: h.script, tone: "fg" },
            {
              text: ` ${fmtMs(h.ms)}ms`,
              tone: failed ? "bad" : msTone(h.ms),
              bold: failed,
            },
            ...(failed
              ? [{ text: ` status ${h.status}`, tone: "bad" as const }]
              : []),
            {
              text: ` · ${h.runs} ${h.runs === 1 ? "run" : "runs"}`,
              tone: "comment",
            },
          ],
          input.columns,
        ),
      };
    }),
  ];
}

function detailLines(row: SnapshotRow, snapshot: Snapshot, columns: number) {
  const lines: Line[] = [
    {
      key: "detail-head",
      segs: fit(
        [
          {
            text: `last ${row.recent.length} ${row.recent.length === 1 ? "record" : "records"} · press the row or Esc to go back`,
            tone: "comment",
          },
        ],
        columns,
      ),
    },
  ];
  const width = Math.max(0, ...row.chain.map((c) => c.plugin.length));
  row.recent.forEach((rec, r) => {
    lines.push({
      key: `rec-${r}`,
      segs: fit(
        [
          { text: ageLabel(snapshot, rec.at), tone: "muted" },
          ...(rec.rejected
            ? [{ text: " · rejected", tone: "bad" as const, bold: true }]
            : []),
        ],
        columns,
      ),
    });
    rec.links.forEach((l, i) => {
      lines.push({
        key: `rec-${r}-${i}`,
        segs: fit(
          [
            { text: "  " },
            { text: l.plugin.padEnd(width), tone: "fg" },
            { text: ` ${fmtMs(l.ms).padStart(6)}ms `, tone: msTone(l.ms) },
            { text: l.outcome, tone: "comment" },
          ],
          columns,
        ),
      });
    });
  });
  return lines;
}

export function layoutPane(input: PaneInput): Line[] {
  const lines = [...header(input), ...troubleLines(input)];
  const engine = input.logStatus === "none" ? ENGINE_LABEL : "engine";
  const snapshot = input.snapshot;
  if (!snapshot || snapshot.rows.length === 0) {
    lines.push({
      key: "empty",
      segs: fit(
        [{ text: "no traced events yet", tone: "comment" }],
        input.columns,
      ),
    });
    lines.push(...commandHookLines(input));
    return lines;
  }
  const picked = input.selected
    ? snapshot.rows.find((r) => r.key === input.selected)
    : undefined;
  if (picked) {
    lines.push({
      key: ROW_PREFIX + picked.key,
      segs: fit(rowSegs(picked, engine), input.columns),
    });
    lines.push(...detailLines(picked, snapshot, input.columns));
    return lines;
  }
  for (const row of snapshot.rows)
    lines.push({
      key: ROW_PREFIX + row.key,
      segs: fit(rowSegs(row, engine), input.columns),
    });
  lines.push(...commandHookLines(input));
  return lines;
}

export type PaneProps = PaneInput & { table: any };

function lineEl(table: any, line: Line) {
  const { Box, Text, Button } = table;
  return (
    <Box key={line.key}>
      {line.segs.map((s) =>
        s.press ? (
          <Button
            key={s.press}
            label={s.text}
            plain
            onPress={() => undefined}
          />
        ) : (
          <Text
            color={s.tone ? paint(s.tone) : undefined}
            bold={s.bold ? true : undefined}
            dimColor={s.dim ? true : undefined}
          >
            {s.text}
          </Text>
        ),
      )}
    </Box>
  );
}

export function pane(input: PaneProps) {
  const { Box } = input.table;
  return (
    <Box flexDirection="column">
      {layoutPane(input).map((l) => lineEl(input.table, l))}
    </Box>
  );
}

