import type { PaintMode, Tone } from "../types/views-state";

// Tone table from docs/reference/theme-tokens.md. A tone with a proven theme
// key follows the owner's Claude theme in `theme` mode; the rest use hex.

export const TONES = Object.freeze({
  fg: { hex: "#c0caf5", ansi: "whiteBright" },
  muted: { hex: "#9aa5ce", ansi: "white" },
  comment: { hex: "#565f89", ansi: "blackBright" },
  accent: { hex: "#7aa2f7", ansi: "blue", themeKey: "claude" },
  info: { hex: "#7dcfff", ansi: "cyan", themeKey: "suggestion" },
  ok: { hex: "#9ece6a", ansi: "green", themeKey: "success" },
  warn: { hex: "#e0af68", ansi: "yellow", themeKey: "warning" },
  owner: { hex: "#ff9e64", ansi: "yellowBright" },
  bad: { hex: "#f7768e", ansi: "red", themeKey: "error" },
  violet: { hex: "#bb9af7", ansi: "magenta" },
  teal: { hex: "#73daca", ansi: "cyanBright" },
  indigo: { hex: "#3d59a1", ansi: "blue" },
  bg: { hex: "#1a1b26", ansi: "black" },
  redRowBg: { hex: "#4a272f", ansi: "red" },
} satisfies Record<string, Tone>);

export type ToneName = keyof typeof TONES;

export function paint(tone: ToneName, mode: PaintMode = "theme"): string {
  const t: Tone = TONES[tone];
  if (mode === "ansi") return t.ansi;
  if (mode === "theme" && t.themeKey) return t.themeKey;
  return t.hex;
}

// Glyph policy. Text takes single-width symbols. Raster takes blocks, box
// drawing, braille and ASCII. The Text fallback for the desktop Code tab
// draws the crest and so also takes the blocks.
export const GLYPH_POLICY = Object.freeze({
  text: Object.freeze([..."●○◆◇◐◉■✓✗×~!▸▾·…━─└⎿›‹≠⇡"]),
  raster: Object.freeze([
    [0x2580, 0x259f],
    [0x2500, 0x257f],
    [0x2800, 0x28ff],
    [0x20, 0x7e],
  ] as const),
  banned: Object.freeze([..."⚠✔✅"]),
});

export function isTextGlyph(ch: string): boolean {
  const cp = ch.codePointAt(0) ?? 0;
  return (cp >= 0x20 && cp <= 0x7e) || GLYPH_POLICY.text.includes(ch);
}

export function isRasterGlyph(cp: number): boolean {
  return GLYPH_POLICY.raster.some(([lo, hi]) => cp >= lo && cp <= hi);
}

export function isBlockGlyph(cp: number): boolean {
  return cp >= 0x2580 && cp <= 0x259f;
}

