// PluginState contract for chain-inspector. Every key holds plain JSON data.

// One link of a recorded chain. `received` and `returned` are never kept.
export type LinkRecord = {
  index: number;
  plugin: string;
  tier: string;
  outcome: string;
  ms: number;
};

// One traced dispatch.
export type TraceRecord = {
  event: string;
  key: string;
  at: number;
  links: LinkRecord[];
  // True when the last link is the engine's own entry.
  endsAtEngine: boolean;
  // True when `next(e)` rejected.
  rejected: boolean;
};

export type Aggregate = {
  count: number;
  meanMs: number;
  maxMs: number;
};

// A mod suspected of ending a shared chain: its last records on the key were
// short and ended at it. `checkedAt` is when the debug log was last read for it.
export type Suspect = {
  key: string;
  event: string;
  plugin: string;
  checkedAt: number | null;
};

// A plugin's new sample on a key that ran over its earlier mean.
export type Slowdown = {
  plugin: string;
  key: string;
  event: string;
  sample: number;
  mean: number;
};

// Confirmed trouble kept for the session: an ender the debug log names, or a
// slowdown. `sample` and `mean` are set for a slowdown.
export type TroubleItem = {
  kind: "ender" | "slow";
  plugin: string;
  key: string;
  event: string;
  at: number;
  sample?: number;
  mean?: number;
};

export type TraceBuffer = {
  // Records added since the session began.
  total: number;
  // True while a snapshot flush is scheduled.
  armed: boolean;
  // The most links seen above the inspector in any trace.
  maxAbove: number;
  // Keys, least recently dispatched first.
  order: string[];
  records: Record<string, TraceRecord[]>;
  aggregates: Record<string, Record<string, Aggregate>>;
  // Suspected enders by key. A full record on the key removes its entry.
  suspects: Record<string, Suspect>;
  // Mods that ended the chain of a component they draw (an owned `ui.render`
  // component) this session. The debug log cannot tell such a draw from a
  // shared-surface end, so these mods are never confirmed from it.
  ownedEnders: string[];
};

// One mod `plugin.register` judged.
export type PluginRecord = {
  name: string;
  tier: string;
  provenance: string;
  events: string[];
};

export type Registry = {
  plugins: PluginRecord[];
  // Event patterns the star hook traces, from every judged mod's `uses`.
  traced: string[];
};

export type SnapshotLink = {
  plugin: string;
  tier: string;
  meanMs: number;
  maxMs: number;
  count: number;
  // True for a builtin plugin's link, read from the debug log.
  builtin?: boolean;
};

// One builtin plugin's settled time on one event, from the debug log. The
// samples of an event are its latest dispatch, innermost builtin first.
export type BuiltinSample = {
  name: string;
  event: string;
  // As logged, with everything beneath the builtin included.
  ms: number;
  // `ms` minus the `ms` of the builtin settled just before it, floored at 0.
  ownMs: number;
};

// One command hook, from the debug log's `Hooks:` lines. The command itself is
// never kept; `script` is the script's file name only.
export type CommandHook = {
  event: string;
  matcher: string | null;
  // `settings`, or the plugin's name without its marketplace.
  source: string;
  script: string;
  // Latest run.
  ms: number;
  runs: number;
  // Exit status of the latest run.
  status: number;
};

// What one pass over the debug log yields.
export type ParsedLog = {
  // `<plugin> <event>` for each `answered <event> without next()` line.
  enders: string[];
  builtins: BuiltinSample[];
  hooks: CommandHook[];
};

// `none` when there is no debug log, `reading` while it is read, `frozen` once
// it passes the size limit.
export type LogStatus = "none" | "reading" | "frozen";

export type SnapshotRow = {
  key: string;
  event: string;
  chain: SnapshotLink[];
  endsAtEngine: boolean;
  // Newest first.
  recent: TraceRecord[];
};

export type SelfCheck = {
  // Links sitting above the inspector in the widest trace seen.
  above: number;
  // Enabled plugins keyed before the inspector that it never judged.
  names: string[];
  // False when settings gave no enabledPlugins, so `names` is unknown.
  namesKnown: boolean;
};

export type Snapshot = {
  // Counts snapshot writes.
  seq: number;
  at: number;
  rows: SnapshotRow[];
  selfCheck: SelfCheck;
  suspects: Suspect[];
  // Command hooks from the debug log, slowest first. Absent without a log.
  commandHooks?: CommandHook[];
};

declare module "claude-code" {
  interface PluginState {
    "chain-inspector": {
      registry: Registry;
      buffer: TraceBuffer;
      snapshot: Snapshot | null;
      tracing: boolean;
      paneOpen: boolean;
      selected: string | null;
      // Confirmed enders and slowdowns, kept for the session.
      trouble: TroubleItem[];
      // The note the PromptHint line carries while an unasked pane waits.
      hintTail: string | null;
      logStatus: LogStatus;
    };
  }
}
